From fc0adb59a418591a571b1b13a07f75214fa3ebb9 Mon Sep 17 00:00:00 2001
From: Rui Casais <rcasais@gmail.com>
Date: Mon, 2 Nov 2026 13:42:19 +0000
Subject: [PATCH] notes: acquire panel input before focusing inline editors

Request panel keyboard interactivity before focusing a clicked inline note.
Retain accepting-input status for the focused inline editor and defer only
releasing the previous editor's status when focus changes between notes.

Keep saving synchronous before the inactive text binding restores noteText,
and exclude compact popup editors from panel input acquisition.

BUG: 527546
---
 applets/notes/qml/main.qml | 22 +++++++++++++++++-----
 1 file changed, 17 insertions(+), 5 deletions(-)

diff --git a/applets/notes/qml/main.qml b/applets/notes/qml/main.qml
index 63a6409ba..433a21651 100644
--- a/applets/notes/qml/main.qml
+++ b/applets/notes/qml/main.qml
@@ -267,16 +267,28 @@ PlasmoidItem {
                     }

                     onActiveFocusChanged: {
-                        const window = Window.window;
-                        if (activeFocus && window && (window.flags & Qt.WindowDoesNotAcceptFocus)) {
-                            Plasmoid.status = PlasmaCore.Types.AcceptingInputStatus
-                        } else {
-                            Plasmoid.status = PlasmaCore.Types.ActiveStatus
+                        if (activeFocus && root.inPanel && !root.compactInPanel) {
+                            Plasmoid.status = PlasmaCore.Types.AcceptingInputStatus;
+                        } else if (!activeFocus) {
+                            // Save before the inactive editor's text binding restores note.noteText.
                             root.note.save(text);
+                            // Let the newly focused note request input before releasing ours.
+                            Qt.callLater(() => {
+                                if (!mainTextArea.activeFocus) {
+                                    Plasmoid.status = PlasmaCore.Types.ActiveStatus;
+                                }
+                            });
                         }
                     }

                     onPressed: event => {
+                        if (event.button === Qt.LeftButton || event.button === Qt.RightButton) {
+                            // A non-interactive panel cannot gain activeFocus until input is enabled.
+                            if (root.inPanel && !root.compactInPanel) {
+                                Plasmoid.status = PlasmaCore.Types.AcceptingInputStatus;
+                            }
+                            forceActiveFocus(Qt.MouseFocusReason);
+                        }
                         if (event.button === Qt.RightButton) {
                             event.accepted = true;
                             contextMenu.popup();
-- 
